import{z as A,x as s,o as E,c as p,q as n,j as t,D as a,d as r,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Reflexion","description":"","frontmatter":{"title":"Reflexion","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reflexion.md","filePath":"llm/reflexion.md","lastUpdated":1791063341000}'),B={name:"llm/reflexion.md"};function c(d,e,h,f,m,D){const o=s("Mermaid");return E(),p("div",null,[e[2]||(e[2]=n('<h1 id="reflexion" tabindex="-1">Reflexion <a class="header-anchor" href="#reflexion" aria-label="Permalink to &quot;Reflexion&quot;">​</a></h1><div class="epigraph"><p>用语言写下的反馈当强化学习的信号：智能体在失败后生成一段反思，存入记忆，在下一回合的同类任务上条件于这段话再试。</p><footer>—— Shinn et al., Reflexion: Language Agents with Verbal Reinforcement Learning, NeurIPS 2023</footer></div><p><a href="/llm/react-prompting">上一课</a>用固定槽位交错示范 Thought、可解析 Action、以及宿主回填的 Observation；长轨迹上格式会漂。轨迹在单次任务内交错，任务一结束，失败原因并不自动进入下一次尝试。缺口是 Reflexion：评估器判定成败，再生成口头反思写入记忆，供下一回合 Actor 条件化。本课写这条记忆—反思—再试，不更新权重，也不把一般 RLHF 讲成同一算法。必须用同等重试次数的无反思基线，才能把增益算在反思上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单次 ReAct 或 CoT 失败后，重试若只用同一提示，模型往往会重复同一条死路：同样的错工具参数、同样的错假设。人类会在试卷空白处写「不要漏单位」，下次看见同类题就先看一眼。需要一种可写、可检索、仍是文本的失败记忆，使第 \\(k+1\\) 次尝试条件于第 \\(k\\) 次的教训，而不是条件于空洞的「再仔细一点」。</p><p>Reflexion 要回答的是：反思文本写什么、谁来评成功、记忆如何截断。若反思只是「我应该更认真」，下一回合没有可执行约束。若评估器不可靠，反思会朝错误原因努力，把系统锁在漂亮的错误叙事里。它也要与单次任务内的 Observation 区分：观察是环境即时返回；反思是跨尝试的元文本。</p><h3 id="口头回报代替参数更新" tabindex="-1">口头回报代替参数更新 <a class="header-anchor" href="#口头回报代替参数更新" aria-label="Permalink to &quot;口头回报代替参数更新&quot;">​</a></h3><p>经典 RL 用标量 \\(R\\) 更新 \\(\\theta\\)。语言智能体的尝试次数往往很少，轨迹是离散文本，用 REINFORCE 更新大模型既贵又不稳。Reflexion 把 \\(R\\) 映射成一段话 \\(m\\)，通过提示拼接改变下一回合的 \\(\\pi(\\cdot\\mid x,m)\\)。学习发生在上下文里，随会话或作业批次消失，除非宿主把 \\(m\\) 持久化。这是特性也是限制：换模型、换系统提示，记忆不会自动迁移到权重里。</p><p><span class="marginnote">标题里的 reinforcement 容易让人写成 PPO。原文明确是 verbal reinforcement：没有反向传播。后训练若拿反思轨迹做 SFT，那是另一条线，不要写进 NeurIPS 2023 方法的必要条件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三角色，可以是同一模型的三种提示，也可以是分开的检查器。Actor：条件于任务、工具说明、以及记忆中的反思，生成一条 ReAct 式或 CoT 式轨迹。Evaluator：对终局打分——单元测试通过、环境成功信号、或启发式（答案是否可解析）。失败则进入反思提示：输入为轨迹摘要（不要原文无限长）、评估结果、任务说明，输出为若干条具体、指向可改行为的句子。宿主把反思 append 到该任务（或该任务类型）的记忆槽，再开新回合，Actor 的系统段或前缀里列出最近若干条。成功则可清记忆或保留正向笔记；原文主路径强调失败驱动。</p><p>轨迹摘要要结构化：用了哪些动作、哪一步评估失败、最后的错误观察。把整页 HTML 塞进反思提示，模型会写空洞感想。反思输出应限制条数与长度，并最好带可核对的承诺（「下次先调用 schema 校验再搜」），而不是情绪。记忆检索默认用同一任务的近期条目；跨任务共用记忆会串味，除非按任务类型分桶。</p>',12)),(E(),t(i,null,{default:a(()=>[l(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20ACT%5B%22Actor%20%E7%94%9F%E6%88%90%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20ACT%20--%3E%20EV%5B%22Evaluator%22%5D%0A%20%20EV%20--%3E%20OK%7B%22%E6%88%90%E5%8A%9F%3F%22%7D%0A%20%20OK%20--%3E%7C%E6%98%AF%7C%20DONE%5B%22%E7%BB%93%E6%9D%9F%22%5D%0A%20%20OK%20--%3E%7C%E5%90%A6%7C%20REF%5B%22%E7%94%9F%E6%88%90%20Self-Reflection%22%5D%0A%20%20REF%20--%3E%20MEM%5B%22%E5%86%99%E5%85%A5%E6%83%85%E6%99%AF%E8%AE%B0%E5%BF%86%22%5D%0A%20%20MEM%20--%3E%20ACT%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n('<h3 id="反思必须指向可改的行为" tabindex="-1">反思必须指向可改的行为 <a class="header-anchor" href="#反思必须指向可改的行为" aria-label="Permalink to &quot;反思必须指向可改的行为&quot;">​</a></h3><p>无效反思：「需要更仔细地推理。」有效反思：「Search 查询应使用完整实体名；上次用了缩写导致空结果。」提示里应用正反示范。评估器能提供的信息决定反思上限：只有 0/1 终局时，模型必须从轨迹里猜原因，可能猜错。能拿到失败的测试名、异常类型、环境的具体非法动作，应原样写入反思提示，让生成变成对错误消息的改写，而不是自由归因。这与 PAL 把 traceback 回填是同一原则。</p><p>重试预算是方法超参。没有上限的反思循环会在不可完成的任务上烧费用，并让记忆堆满互相矛盾的句子。应设最大尝试次数，并在记忆过长时做摘要或只保留最近 \\(n\\) 条。矛盾检测很难自动做，简单策略是新反思覆盖旧的同主题句，或按时间衰减。不要对记忆做向量检索除非任务很多：同一题的几次尝试，线性拼最近几条更稳。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Reflexion 改变的是跨回合的条件分布。第 \\(k+1\\) 次 Actor 看见对第 \\(k\\) 次失败的语言描述，相当于在提示里加入了负样本的文字化梯度。它能打破「同一提示下的模式崩溃」，因为前缀真的变了。它不能打破评估器盲区：若测试套件漏了某类错，反思会认为成功，记忆不再更新。它也不能把一次尝试内部的逐步纠错自动做好——那仍是 ReAct 观察的职责。两层记忆：回合内观察，回合间反思。</p><p><span class="marginnote">「文字化梯度」可以类比教练的赛后复盘：参数更新像把肌肉记忆直接改掉，口头反思则像把「上次起跳太早」写进训练日志，下次上场前读一遍。改的虽不是身体本身，但行为路线确实变了——前提是复盘写得具体，而不是「下次努力」。</span></p><p>相对自洽：自洽并行采样，不读写失败教训；Reflexion 串行，依赖评估器。相对 ToT：ToT 在单次求解的中间状态上搜索；Reflexion 在完整尝试的失败上学习。相对过程监督：PRM 给步骤打分并可能更新或搜索；Reflexion 的评估通常在终局，反思是事后散文。把 Reflexion 接到逐步评估上是自然扩展，但原文不是 PRM。</p><p><span class="marginnote">这几种方法其实在回答同一个问题「怎么提高单任务成功率」：自洽是「多答几遍投票」，ToT 是「一步走错就地回头」，Reflexion 是「这局输了记住教训再来一局」，PRM 是「每走一步都有裁判打分」。先看失败发生在哪一层——采样运气、中间状态还是整局策略——再选方法。</span></p><p><span class="marginnote">记忆是提示的一部分，因此有注入面。不可信环境若能把字符串写进「失败原因」，下一回合 Actor 可能执行记忆里的恶意建议。反思槽必须与用户/网页观察隔离，并由宿主生成，不要让网页内容直接 append 进记忆。</span></p><h3 id="评估器校准决定记忆质量" tabindex="-1">评估器校准决定记忆质量 <a class="header-anchor" href="#评估器校准决定记忆质量" aria-label="Permalink to &quot;评估器校准决定记忆质量&quot;">​</a></h3><p>假失败：评估器过严，反思会针对并不存在的错误改策略，把对的路径改坏。假成功：过宽，错误策略被固化。启发式评估（「答案看起来像数字」）尤其危险。优先用环境真值或测试；不得已用模型当评估器时，应低温度、要求引用轨迹中的具体一步，并允许「无法判断」以免硬给 \\(R\\)。多次尝试的准确率曲线应同时报平均尝试次数，否则把预算换成次数的方法会看起来像免费涨点。</p><p><span class="marginnote">评估器不严时，反思循环是放大器而不是修正器：假如有 20% 的假成功率，一个写错的策略每次重试都有约两成机会被误判「通过」，一旦得逞就写进记忆、下回合照做——重试次数越多，坏策略被固化的机会反而越大。</span></p>',12)),(E(),t(i,null,{default:a(()=>[l(o,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E8%AF%84%E4%BC%B0%E5%99%A8%E7%BB%99%E6%9C%AC%E6%AC%A1%E5%B0%9D%E8%AF%95%E6%89%93%E5%88%86%22%5D%20--%3E%20J%7B%22%E5%88%86%E6%95%B0%E4%B8%8E%E7%9C%9F%E5%AE%9E%E6%88%90%E8%B4%A5%E5%AF%B9%E9%BD%90%3F%22%7D%0A%20%20J%20--%3E%7C%22%E5%AF%B9%E9%BD%90%22%7C%20GOOD%5B%22%E5%8F%8D%E6%80%9D%E5%BD%92%E5%9B%A0%E5%88%B0%E7%9C%9F%E6%AD%A3%E7%9A%84%E9%94%99%E8%AF%AF%E6%AD%A5%E9%AA%A4%22%5D%0A%20%20GOOD%20--%3E%20FIX%5B%22%E4%B8%8B%E4%B8%80%E5%9B%9E%E5%90%88%E6%94%B9%E5%AF%B9%E5%9C%B0%E6%96%B9%22%5D%0A%20%20J%20--%3E%7C%22%E8%BF%87%E4%B8%A5%3A%20%E5%81%87%E5%A4%B1%E8%B4%A5%22%7C%20HARS%5B%22%E5%8F%8D%E6%80%9D%E8%B4%A3%E6%80%AA%E6%9C%AC%E6%B2%A1%E9%94%99%E7%9A%84%E8%B7%AF%E5%BE%84%22%5D%0A%20%20HARS%20--%3E%20BREAK%5B%22%E6%8A%8A%E8%83%BD%E7%94%A8%E7%9A%84%E7%AD%96%E7%95%A5%E6%94%B9%E5%9D%8F%22%5D%0A%20%20J%20--%3E%7C%22%E8%BF%87%E5%AE%BD%3A%20%E5%81%87%E6%88%90%E5%8A%9F%22%7C%20LEN%5B%22%E9%94%99%E8%AF%AF%E7%AD%96%E7%95%A5%E8%A2%AB%E5%88%A4%E4%B8%BA%E6%88%90%E5%8A%9F%22%5D%0A%20%20LEN%20--%3E%20STUCK%5B%22%E5%9D%8F%E7%AD%96%E7%95%A5%E5%86%99%E8%BF%9B%E8%AE%B0%E5%BF%86%E5%B9%B6%E5%9B%BA%E5%8C%96%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Reflexion 适合有清晰成功信号、允许几次重试、失败模式可语言化的任务：编程练习、带胜负的环境、可核对的问答。开放聊天没有二元成功，反思会变成自我说教。不可重试的一次 API 调用也不适合先失败再学。记忆持久化要考虑隐私与过期：上周的 API 报错格式这周已变，旧反思有害。不要把 Reflexion 当成训练算法去替代对 Actor 的 SFT；它可以产生更好的轨迹再拿去蒸馏，那是流水线，不是原文必须步骤。</p><p>与 ReAct 提示形态一起用时：Actor 仍遵守 Thought/Action 槽位；反思放在系统段或记忆段，不要写进 Observation。Observation 是环境，反思是元策略。混在同一槽会让模型把教训当成当前工具返回。引用以 Shinn et al. NeurIPS 2023 为准；具体环境分数随 Actor 基座与工具变化。</p><p><span class="marginnote">「多试几次」本身就会涨点。对照实验必须包含无反思的同等次数重试（只换随机种子或温度）。否则增益可能来自 Best-of-N，而不是来自那段话。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Reflexion 用评估器判定尝试成败，再生成口头反思写入记忆，供下一回合 Actor 条件化。</li><li>它是上下文里的强化，不更新权重；学习随记忆的生命周期结束。</li><li>反思要具体、可执行；评估信号越结构化，归因越不胡编。</li><li>回合内观察与回合间记忆必须分槽，并防注入。</li><li>必须用同等重试次数的无反思基线，才能把增益算在反思上。</li><li>出处：Shinn et al., <em>Reflexion: Language Agents with Verbal Reinforcement Learning</em>, NeurIPS 2023。</li></ul>',6))])}const x=A(B,[["render",c]]);export{u as __pageData,x as default};
